// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: bebasFamily } = loadBebas();
const { fontFamily: montserratFamily } = loadMontserrat();



export type SlotMachineProfitProps = Record<string, any>;

const SlotMachineProfit: React.FC<SlotMachineProfitProps> = ({
  backgroundColor = "#0f0f1a",
  transparentBackground = false,
  durationInSeconds = 6,
  profitAmount = 75450,
  currencySymbol = "$",
  headlineText = "MEGA WIN",
  subLabelText = "TOTAL PROFIT",
  goldColor = "#FFD700",
  accentColor = "#FF1493",
  panelBackgroundColor = "#111111",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety logic for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Sizing baseline for responsiveness
  const s = Math.min(width, height);

  // --- Animation Timings ---
  const ENTRANCE_START = 10;
  const COUNT_START = 25;
  const COUNT_DURATION = 60;
  const EXIT_START = durationInSeconds * fps - 20;

  // --- Springs & Interpolations ---
  // 1. Popup Entrance Scale
  const entranceScale = spring({
    frame: frame - ENTRANCE_START,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });

  // 2. Popup Exit Scale
  const exitScale = spring({
    frame: frame - EXIT_START,
    fps,
    config: { damping: 15, mass: 1 },
  });

  // Combine for final scale (pops in, then shrinks out at the end)
  const currentScale = entranceScale - exitScale;

  // 3. Profit Counter Number
  const countProgress = interpolate(
    frame,
    [COUNT_START, COUNT_START + COUNT_DURATION],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.exp), // Exponential out for slot machine slow-down effect
    }
  );
  
  const currentProfit = Math.floor(profitAmount * countProgress);
  const formattedProfit = new Intl.NumberFormat("en-US").format(currentProfit);

  // 4. Background Ray Rotation
  const rayRotation = (frame * 0.5) % 360;

  // 5. Pulsing Glow Effect
  const pulseScale = interpolate(
    Math.sin(frame * 0.15),
    [-1, 1],
    [0.9, 1.1]
  );
  const glowOpacity = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.4, 0.8]
  );

  // 6. Marquee Lights Flashing (Pure function based on frame)
  const isFlashA = Math.floor(frame / 6) % 2 === 0;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Dimmer Overlay (only shows if not transparent) */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            backgroundColor: "rgba(0,0,0,0.6)",
            opacity: interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" }),
            transition: "none",
          }}
        />
      )}

      {/* Main Popup Container */}
      <div
        style={{
          width: width * 0.6,
          height: height * 0.45,
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${Math.max(0, currentScale)})`,
          transition: "none",
        }}
      >
        {/* Pulsing Outer Glow */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: s * 0.04,
            backgroundColor: goldColor,
            filter: `blur(${s * 0.08}px)`,
            opacity: glowOpacity,
            transform: `scale(${pulseScale})`,
            transition: "none",
          }}
        />

        {/* Solid Panel Background */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backgroundColor: panelBackgroundColor,
            borderRadius: s * 0.04,
            border: `${s * 0.008}px solid ${goldColor}`,
            boxShadow: `inset 0 0 ${s * 0.05}px rgba(0,0,0,0.8)`,
            overflow: "hidden",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 1,
            transition: "none",
          }}
        >
          {/* Rotating Sunburst/Rays Background */}
          <svg
            viewBox="0 0 100 100"
            style={{
              position: "absolute",
              width: "200%",
              height: "200%",
              opacity: 0.15,
              transform: `rotate(${rayRotation}deg)`,
              transformOrigin: "center center",
              transition: "none",
            }}
          >
            {Array.from({ length: 16 }).map((_, i) => (
              <polygon
                key={i}
                points="50,50 40,0 60,0"
                fill={goldColor}
                style={{
                  transform: `rotate(${(360 / 16) * i}deg)`,
                  transformOrigin: "50px 50px",
                  transition: "none",
                }}
              />
            ))}
          </svg>

          {/* Inner Content Spacer */}
          <div style={{ height: s * 0.04 }} />

          {/* Sub Label (TOTAL PROFIT) */}
          <div
            style={{
              fontFamily: montserratFamily,
              color: "white",
              fontSize: s * 0.03,
              fontWeight: 800,
              letterSpacing: s * 0.008,
              opacity: 0.8,
              zIndex: 2,
              transition: "none",
            }}
          >
            {subLabelText}
          </div>

          {/* Main Profit Number */}
          <div
            style={{
              fontFamily: bebasFamily,
              color: goldColor,
              fontSize: s * 0.18,
              lineHeight: 1,
              marginTop: s * 0.01,
              textShadow: `
                0px ${s * 0.006}px 0px #b8860b,
                0px ${s * 0.012}px ${s * 0.02}px rgba(0,0,0,0.8),
                0px 0px ${s * 0.04}px ${goldColor}
              `,
              fontVariantNumeric: "tabular-nums", // Prevents jitter during count
              zIndex: 2,
              transition: "none",
            }}
          >
            {currencySymbol}
            {formattedProfit}
          </div>
        </div>

        {/* Headline / Badge Overlapping Top Edge */}
        <div
          style={{
            position: "absolute",
            top: -s * 0.04,
            backgroundColor: accentColor,
            padding: `${s * 0.015}px ${s * 0.06}px`,
            borderRadius: s * 0.05,
            border: `${s * 0.006}px solid white`,
            boxShadow: `0px ${s * 0.01}px ${s * 0.02}px rgba(0,0,0,0.5)`,
            zIndex: 3,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${entranceScale === 1 ? (Math.sin(frame * 0.2) * 0.02 + 1) : 1})`, // Gentle breathing when settled
            transition: "none",
          }}
        >
          <div
            style={{
              fontFamily: montserratFamily,
              color: "white",
              fontSize: s * 0.04,
              fontWeight: 900,
              fontStyle: "italic",
              letterSpacing: s * 0.005,
              textShadow: `0px ${s * 0.004}px 0px rgba(0,0,0,0.3)`,
              transition: "none",
            }}
          >
            {headlineText}
          </div>
        </div>

        {/* Marquee Border Lights Simulation */}
        <div
          style={{
            position: "absolute",
            width: "calc(100% + 20px)",
            height: "calc(100% + 20px)",
            border: `${s * 0.01}px dashed ${isFlashA ? goldColor : "transparent"}`,
            borderRadius: s * 0.05,
            zIndex: 0,
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            width: "calc(100% + 20px)",
            height: "calc(100% + 20px)",
            border: `${s * 0.01}px dashed ${!isFlashA ? "white" : "transparent"}`,
            borderRadius: s * 0.05,
            transform: "rotate(180deg)", // Offset the dashes
            zIndex: 0,
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default SlotMachineProfit;